        if len(operators) == 0:
            return operands[0]

        precedence = {'**': 3, '*': 2, '/': 2, '+': 1, '-': 1}
        stack_operators = []
        stack_operands = []

        for i in range(len(operators)):
            while stack_operators and precedence[operators[i]] <= precedence[stack_operators[-1]]:
                op = stack_operators.pop()
                num2 = stack_operands.pop()
                num1 = stack_operands.pop()

                if op == '+':
                    stack_operands.append(num1 + num2)
                elif op == '-':
                    stack_operands.append(num1 - num2)
                elif op == '*':
                    stack_operands.append(num1 * num2)
                elif op == '/':
                    stack_operands.append(num1 // num2)
                elif op == '**':
                    stack_operands.append(num1 ** num2)

            stack_operators.append(operators[i])
            stack_operands.append(operands[i])

        while stack_operators:
            op = stack_operators.pop()
            num2 = stack_operands.pop()
            num1 = stack_operands.pop()

            if op == '+':
